## Code Example
```javascript
// Pseudocode: bounded mailbox in a tiny OS
class Mailbox {
  constructor(cap) {
    this.buf = new Array(cap);
    this.head = 0; this.tail = 0; this.count = 0; this.cap = cap;
    this.lock = new Mutex();
    this.notEmpty = new CondVar();
    this.notFull = new CondVar();
  }
}

function trySend(mb, m) {
  mb.lock.lock();
  if (mb.count === mb.cap) { mb.lock.unlock(); return false; }
  mb.buf[mb.tail] = m;
  mb.tail = (mb.tail + 1) % mb.cap;
  mb.count++;
  mb.notEmpty.signal();
  mb.lock.unlock();
  return true;
}

function blockingRecv(mb, out) {
  mb.lock.lock();
  while (mb.count === 0) {
    mb.notEmpty.wait(mb.lock);
  }
  *out = mb.buf[mb.head];
  mb.head = (mb.head + 1) % mb.cap;
  mb.count--;
  mb.notFull.signal();
  mb.lock.unlock();
}
```

## Why This Is Asked

Tests the ability to design scalable I/O budgeting, cross-CPU coordination, and NUMA-aware fairness under heavy multi-tenant workloads.

## Key Concepts

- Per-VM isolation and quotas
- NUMA-aware accounting
- Token-bucket throttling
- Cross-CPU coordination via IPI
- CAS-based atomic updates

## Code Example

```c
struct vm_budget {
    atomic_long budget_bytes;
    atomic_long tokens;
    int numa_node;
};

void refill(struct vm_budget *vb) {
    atomic_fetch_add(&vb->tokens, REFILL_TOKEN);
}

static bool try_consume(struct vm_budget *vb, long cost) {
    long old, new;
    do {
        old = atomic_load(&vb->tokens);
        if (old < cost)
            return false;
        new = old - cost;
    } while (!atomic_compare_exchange_weak(&vb->tokens, &old, new));
    return true;
}

void submit_io(struct vm_budget *vb, struct bio *bio) {
    if (!try_consume(vb, bio->size))
        enqueue_throttled(vb->numa_node, bio);
    else
        dispatch_io(bio);
}
```

